values
  ('3c2d9f3c-ed67-41a2-8d9b-28646f38a092', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', null, 'topic'::public.curated_course_node_type, 'Syntax of the Spanish Sentence', 'This opening unit gives students a working map of how Spanish sentences are built so that later choices about mood, pronouns, style, and revision have a shared grammatical vocabulary.', 0),
