  ('71a61671-2267-45b6-8222-76fb2d3658cb', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', '6d6c1d59-dd5e-402d-b6ed-1168e4a9a4d0', 'concept'::public.curated_course_node_type, 'Placement of modifiers and adverbs', null, 3),
  ('8cd55276-12f1-4eaa-b358-7ba3770a04b3', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', null, 'topic'::public.curated_course_node_type, 'Mood, Modality, and Subjunctive Choice', 'The subjunctive becomes a tool for meaning: uncertainty, evaluation, influence, anticipation, and stance. Students learn when mood choice changes what a sentence claims.', 1),
