  ('50f8b16f-730d-46e2-a994-737b252c0b81', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', '98b9ed76-3376-4dd5-b1a5-80eef87e3fb9', 'concept'::public.curated_course_node_type, 'Preterite versus imperfect', null, 0),
