  ('5cc1e0df-c041-47f1-956c-6e74ba6e9b3c', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', null, 'topic'::public.curated_course_node_type, 'Uses of se, Voice, and Argument Structure', 'The many uses of se are taught as a system connected to agency, emphasis, lexical meaning, and sentence perspective.', 4),
