  ('e3e5cbff-a65a-419a-ac24-318dfbf9cf84', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', 'fda88413-968c-4683-a225-336ac1cd2e7f', 'concept'::public.curated_course_node_type, 'Punctuation with embedded clauses', null, 3),
  ('fd30d56e-257f-4d34-894e-bd57d6cd9379', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', null, 'topic'::public.curated_course_node_type, 'Cohesion, Discourse Connectors, and Information Structure', 'This unit shifts from sentence-level correctness to paragraph-level movement. Students learn how Spanish academic prose signals sequence, contrast, cause, concession, and emphasis.', 6),
