  ('c0bbcd25-3952-4702-8f25-8e482ca1aa34', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', 'b9ad88c0-02ce-4281-8d51-c2375629d4dc', 'concept'::public.curated_course_node_type, 'Addition and sequence', null, 0),
