  ('dc846c1e-ba7a-496d-9e01-b8d89a59982c', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', 'b9ad88c0-02ce-4281-8d51-c2375629d4dc', 'concept'::public.curated_course_node_type, 'Reformulation and conclusion', null, 3),
  ('8c9ba84d-446f-4916-8d3b-2b272bcad31e', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', 'fd30d56e-257f-4d34-894e-bd57d6cd9379', 'subtopic'::public.curated_course_node_type, 'Theme-rheme progression', 'Students learn to manage old and new information so paragraphs feel coherent.', 1),
  ('ad1787c6-42ed-4562-a667-b112100ac6f8', 'c5d6e7f8-9a0b-4c80-9d00-1e2f3a4b5c10', '8c9ba84d-446f-4916-8d3b-2b272bcad31e', 'concept'::public.curated_course_node_type, 'Topic sentences in Spanish', null, 0),
