  'Advanced Grammar and Composition develops precise, flexible, and stylistically mature Spanish for upper-division academic work. Students analyze complex grammar in context, revise essays through multiple drafts, and learn to consult authoritative grammar and usage references. The course treats grammar as a writing resource: every structure is linked to clearer argument, stronger paragraph cohesion, and more idiomatic Spanish.',
  $agrcjson${"slug": "advanced-grammar-and-composition", "title": "Advanced Grammar and Composition", "description": "Advanced Grammar and Composition develops precise, flexible, and stylistically mature Spanish for upper-division academic work. Students analyze complex grammar in context, revise essays through multiple drafts, and learn to consult authoritative grammar and usage references. The course treats grammar as a writing resource: every structure is linked to clearer argument, stronger paragraph cohesion, and more idiomatic Spanish.", "topics": [{"id": "3c2d9f3c-ed67-41a2-8d9b-28646f38a092", "type": "topic", "title": "Syntax of the Spanish Sentence", "description": "This opening unit gives students a working map of how Spanish sentences are built so that later choices about mood, pronouns, style, and revision have a shared grammatical vocabulary.", "children": [{"id": "1311be8a-61f8-4b2a-a0fc-4379d27b8d7e", "type": "subtopic", "title": "Clause architecture", "children": [{"id": "11554c41-86c8-4afd-a893-8a1d4c961aaf", "type": "concept", "title": "Simple, compound, and complex clauses"}, {"id": "1e0f9a5b-1356-46f2-a504-2c49fcc5504b", "type": "concept", "title": "Main versus subordinate clauses"}, {"id": "23f26d23-406c-46eb-a006-0bfe979071f5", "type": "concept", "title": "Coordination and subordination"}, {"id": "4301d924-7117-4081-9f9f-80db6b3f787a", "type": "concept", "title": "Constituent order and sentence rhythm"}], "description": "Students learn to identify subject, predicate, complement, adjunct, and embedded clause roles before revising complex prose."}, {"id": "2ef8306e-d803-4344-8be1-49d3b9ae9b92", "type": "subtopic", "title": "Agreement and government", "children": [{"id": "2b64fdfe-4769-4a8c-b561-a6f6220088d4", "type": "concept", "title": "Subject-verb agreement"}, {"id": "e55d58cc-4688-4932-9f56-810ba902dda8", "type": "concept", "title": "Noun-adjective agreement"}, {"id": "3051e76b-9a0c-44d4-adb4-9049f556b643", "type": "concept", "title": "Predicate adjectives and participles"}, {"id": "a7a7d892-b25c-4d15-8f2a-c8b51ed45411", "type": "concept", "title": "Prepositional government and regime"}], "description": "Agreement is treated as a system of relationships, not a set of isolated corrections."}, {"id": "6d6c1d59-dd5e-402d-b6ed-1168e4a9a4d0", "type": "subtopic", "title": "Word order and emphasis", "children": [{"id": "a30316f3-b338-46a8-8b4d-993177f8b00e", "type": "concept", "title": "Canonical SVO order"}, {"id": "8ad33efe-b902-4f37-aaf4-50893c3190b5", "type": "concept", "title": "Fronting for emphasis"}, {"id": "116c10b7-1a55-4c58-ad6e-b698db211517", "type": "concept", "title": "Postverbal subjects"}, {"id": "71a61671-2267-45b6-8222-76fb2d3658cb", "type": "concept", "title": "Placement of modifiers and adverbs"}], "description": "Students practice how Spanish uses position to manage emphasis, topic, focus, and natural flow."}]}, {"id": "8cd55276-12f1-4eaa-b358-7ba3770a04b3", "type": "topic", "title": "Mood, Modality, and Subjunctive Choice", "description": "The subjunctive becomes a tool for meaning: uncertainty, evaluation, influence, anticipation, and stance. Students learn when mood choice changes what a sentence claims.", "children": [{"id": "c6ae1f8d-0b72-4ddc-a48b-6754f51718cc", "type": "subtopic", "title": "Noun clauses", "children": [{"id": "158feed4-689c-4828-a5a2-b7d66aaa2882", "type": "concept", "title": "Wishes and influence"}, {"id": "e6b0fd20-e605-4d10-b306-ffc59fba1c8a", "type": "concept", "title": "Doubt, denial, and probability"}, {"id": "693eb72d-da18-4aea-a160-bdcb184d1d56", "type": "concept", "title": "Emotion and evaluation"}, {"id": "234d8ebe-52a6-44b9-97db-91e4b18498d0", "type": "concept", "title": "Indicative after assertion and certainty"}], "description": "Students connect mood selection to verbs of desire, doubt, emotion, denial, recommendation, and perception."}, {"id": "eb14ca4c-44ad-490d-954f-7b39c04cda8f", "type": "subtopic", "title": "Adjective clauses", "children": [{"id": "f5867ee2-6af6-468c-ba28-7e6733283ace", "type": "concept", "title": "Known versus unknown antecedents"}, {"id": "93ece7a1-ed2d-4d83-ae14-5fa1982798d2", "type": "concept", "title": "Negative antecedents"}, {"id": "6aea07db-665b-491d-94a8-f3d215ebcee8", "type": "concept", "title": "Superlatives and evaluative antecedents"}, {"id": "45a75b99-eae7-4fa1-9206-c0d1b9153943", "type": "concept", "title": "Subjunctive with indefinite reference"}], "description": "The course emphasizes reference: whether the noun is known, unknown, hypothetical, or negated."}, {"id": "e93c7b13-39bb-4248-920f-8e257a6ec4dc", "type": "subtopic", "title": "Adverbial clauses", "children": [{"id": "98f92403-4d84-47bd-87ed-6dff9371716c", "type": "concept", "title": "Time clauses"}, {"id": "9463f02e-c200-4c7e-9b0c-a8fcd83dbf4a", "type": "concept", "title": "Purpose clauses"}, {"id": "6c8287d7-0275-4664-bfcb-b7e913720ed2", "type": "concept", "title": "Concession and condition"}, {"id": "e22837c6-373e-443e-b2bf-3233be7345b6", "type": "concept", "title": "Manner clauses and restrictive contexts"}], "description": "Students distinguish clauses that point to future, hypothetical, habitual, or factual circumstances."}]}, {"id": "7e638ff3-7da3-4bfe-8854-1be8900d592b", "type": "topic", "title": "Tense, Aspect, and Sequence of Tenses", "description": "Advanced writers need temporal control: not only correct verb forms, but also coherent time relationships across paragraphs, summaries, critiques, and arguments.", "children": [{"id": "98b9ed76-3376-4dd5-b1a5-80eef87e3fb9", "type": "subtopic", "title": "Aspect in narration", "children": [{"id": "50f8b16f-730d-46e2-a994-737b252c0b81", "type": "concept", "title": "Preterite versus imperfect"}, {"id": "7d8fb19f-b6d5-408f-b4de-e28c5bc293e9", "type": "concept", "title": "Narrative foreground and background"}, {"id": "20839871-20ee-4134-82c7-bf3f5484e008", "type": "concept", "title": "Perfect tenses"}, {"id": "d720596a-ba90-41a9-861b-195f008e75fc", "type": "concept", "title": "Progressive constructions"}], "description": "Students refine contrasts among completed action, background description, habitual action, and ongoing states."}, {"id": "d491ceca-b186-4bf4-b829-e530a60f03c9", "type": "subtopic", "title": "Sequence of tenses", "children": [{"id": "6d14ffba-a085-41a7-bfdc-dfac02a99974", "type": "concept", "title": "Present-triggered subjunctive"}, {"id": "548c2736-3c79-4399-a28b-3443e72f6c52", "type": "concept", "title": "Past-triggered subjunctive"}, {"id": "73b1a994-4270-43ef-8d6a-1fcb1d2decdf", "type": "concept", "title": "Conditional and future perspectives"}, {"id": "e366d6ed-725a-470d-9add-e9ac1ecb9d6e", "type": "concept", "title": "Reported speech"}], "description": "Students learn how main-clause tense constrains subordinate-clause tense in formal and academic contexts."}, {"id": "04763ef9-ae3d-4786-a80d-9c63953b23db", "type": "subtopic", "title": "Hypothesis and counterfactuality", "children": [{"id": "56f01609-1f2e-4dd5-a6d7-a87eeba27eac", "type": "concept", "title": "Si clauses"}, {"id": "cbab802a-5fef-464e-9b60-7814667e5a12", "type": "concept", "title": "Conditional perfect"}, {"id": "83526c3d-5060-413b-8635-f36cbe31c751", "type": "concept", "title": "Pluperfect subjunctive"}, {"id": "0e734c58-2506-4de3-89f0-09a418c7f068", "type": "concept", "title": "Modal verbs and probability"}], "description": "Students practice the grammar of possible, improbable, and unreal situations."}]}, {"id": "0adc3c2c-d134-49fd-b483-305e3dc38067", "type": "topic", "title": "Pronouns, Clitics, and Reference", "description": "This unit targets the small words that carry a large burden in Spanish: object pronouns, clitics, demonstratives, possessives, and reference chains.", "children": [{"id": "6894a4c6-8582-49a4-b929-74c2112db5c8", "type": "subtopic", "title": "Object pronouns", "children": [{"id": "29fcd8ca-2265-4c76-b483-442906041c9a", "type": "concept", "title": "Direct and indirect objects"}, {"id": "6364624d-fde8-4281-84a4-dd1d220a0558", "type": "concept", "title": "Double-object pronouns"}, {"id": "ef37648e-170c-4655-bcae-ae79a270a4ab", "type": "concept", "title": "Clitic placement with infinitives and gerunds"}, {"id": "9b4fa295-53dc-4224-810d-0e2513b94675", "type": "concept", "title": "Reduplication and emphasis"}], "description": "Students move from form recognition to fluent placement and stylistically natural usage."}, {"id": "f7b4a6a5-a8a7-4c0d-8324-db23563e6c59", "type": "subtopic", "title": "Reference clarity", "children": [{"id": "046f6545-cb6a-4f87-bf58-26f9542ca458", "type": "concept", "title": "Antecedent-pronoun agreement"}, {"id": "8aca95ed-90af-47b7-9237-a50cabde67ff", "type": "concept", "title": "Demonstratives and textual reference"}, {"id": "f46fc495-4574-4621-a147-715002800d38", "type": "concept", "title": "Avoiding ambiguous reference"}, {"id": "99d4c30c-a88d-4202-83e4-56abf0ca5d67", "type": "concept", "title": "Reference in summaries and critiques"}], "description": "Students learn to maintain clear antecedents across longer academic paragraphs."}, {"id": "cd86742f-df75-44b7-a089-50772f503e24", "type": "subtopic", "title": "Regional and normative variation", "children": [{"id": "7dc2c115-3fe6-46a5-9065-4d251445b687", "type": "concept", "title": "Leismo, laismo, and loismo"}, {"id": "e56a4ddb-da73-4409-942e-333a834afde4", "type": "concept", "title": "Vosotros and ustedes"}, {"id": "b324879e-837f-4fc5-adf8-d8e68707c651", "type": "concept", "title": "Voseo awareness"}, {"id": "0ffe0fe8-7a1d-4be8-be8d-c436f1be528d", "type": "concept", "title": "Normative versus descriptive choices"}], "description": "Students compare standard expectations with widespread regional patterns."}]}, {"id": "5cc1e0df-c041-47f1-956c-6e74ba6e9b3c", "type": "topic", "title": "Uses of se, Voice, and Argument Structure", "description": "The many uses of se are taught as a system connected to agency, emphasis, lexical meaning, and sentence perspective.", "children": [{"id": "10a03f3b-678b-4f6c-8d9e-7a58c8a93829", "type": "subtopic", "title": "Core uses of se", "children": [{"id": "516df481-3fbe-4a21-a317-83a2fb2e689e", "type": "concept", "title": "Reflexive se"}, {"id": "2286db9e-3106-43a3-9a4b-9ec361d0cb31", "type": "concept", "title": "Reciprocal se"}, {"id": "ca7896fb-6a2f-44a1-a1ec-bd6f6341e7fa", "type": "concept", "title": "Pronominal verbs"}, {"id": "c9309987-434b-43f3-b5cb-e11c02bb43f1", "type": "concept", "title": "Se with unplanned events"}], "description": "Students learn to classify se forms accurately before using them in formal writing."}, {"id": "fff80ea3-f9c2-4caa-bf5e-9df850d838cc", "type": "subtopic", "title": "Passive and impersonal constructions", "children": [{"id": "50719db3-811f-4dfe-b273-99af6a640b8d", "type": "concept", "title": "Pasiva refleja"}, {"id": "da8ecdb1-7026-4dc8-a10b-a8ee4a29efb1", "type": "concept", "title": "Impersonal se"}, {"id": "41603be1-fe02-4394-8b7f-acbe4d78c32c", "type": "concept", "title": "Ser + participle passives"}, {"id": "4562f33e-7507-482e-a3f8-f6a0cfcace4e", "type": "concept", "title": "Agency and omission of agents"}], "description": "Students practice alternatives to English-like passive sentences."}, {"id": "4a35c863-bdae-446b-b194-3d3189106378", "type": "subtopic", "title": "Argument structure", "children": [{"id": "8799e813-0677-4fe4-b8c6-073c5a1f37ec", "type": "concept", "title": "Transitive and intransitive patterns"}, {"id": "67dd837a-a6c6-4946-8363-af510cfedb9a", "type": "concept", "title": "Verbs of change"}, {"id": "661756cd-3e4e-43e7-85a0-959801fdec9d", "type": "concept", "title": "Psychological verbs such as gustar"}, {"id": "1bf9e260-c73a-4f03-a604-d3c0bbc77417", "type": "concept", "title": "Causative and anticausative alternations"}], "description": "Students examine how verbs select participants and how that affects prepositions, pronouns, and meaning."}]}, {"id": "b2117481-eff8-43f2-9006-006b50f4dd15", "type": "topic", "title": "Subordination and Clause Combining", "description": "Students learn to expand, compress, and vary sentence structure without losing clarity. The goal is syntactic maturity, not long sentences for their own sake.", "children": [{"id": "98d562df-4e2d-4309-96ae-46444400aac4", "type": "subtopic", "title": "Relative clauses", "children": [{"id": "cf954fce-3f41-44fe-9bac-d3e0153ab656", "type": "concept", "title": "Que, quien, cual, cuyo"}, {"id": "de1071be-3760-4fed-a97c-35e4e296aacc", "type": "concept", "title": "Restrictive and nonrestrictive clauses"}, {"id": "3edf6d93-4ef7-468e-846e-86253c3dcb14", "type": "concept", "title": "Preposition + relative pronoun"}, {"id": "22b1e0d1-fed6-4fa5-a43b-b4dbdc0ac860", "type": "concept", "title": "Relative clauses in academic definitions"}], "description": "Students use relative clauses to add precision while controlling agreement, prepositions, and register."}, {"id": "ca179d69-6895-4992-9d6d-2715cb8b7495", "type": "subtopic", "title": "Nominalizations and infinitive clauses", "children": [{"id": "3a843f73-deb3-4eb9-aced-66cee5ca4db9", "type": "concept", "title": "Infinitive clauses"}, {"id": "b5e59c1f-a9fb-4685-bc63-d5915ed68705", "type": "concept", "title": "Gerund cautions"}, {"id": "8ab75ee0-c22a-41bd-9e24-34eecfd49a42", "type": "concept", "title": "Nominalized actions"}, {"id": "38d32697-5de5-4b55-bb6c-76e438c84bae", "type": "concept", "title": "Avoiding over-nominalization"}], "description": "Students practice compact academic style and alternatives to repeated subordinate clauses."}, {"id": "fda88413-968c-4683-a225-336ac1cd2e7f", "type": "subtopic", "title": "Sentence combining for style", "children": [{"id": "50a25c7a-1db3-49d7-8b51-7273551bfdff", "type": "concept", "title": "Combining short sentences"}, {"id": "cad0dcbd-b333-4c50-acbe-d5e59ccc58c4", "type": "concept", "title": "Breaking overloaded sentences"}, {"id": "0f9ae3f4-b0f7-436f-97e5-4a354b428d2e", "type": "concept", "title": "Parallel structure"}, {"id": "e3e5cbff-a65a-419a-ac24-318dfbf9cf84", "type": "concept", "title": "Punctuation with embedded clauses"}], "description": "Revision workshops focus on sentence variety, logic, and rhythm."}]}, {"id": "fd30d56e-257f-4d34-894e-bd57d6cd9379", "type": "topic", "title": "Cohesion, Discourse Connectors, and Information Structure", "description": "This unit shifts from sentence-level correctness to paragraph-level movement. Students learn how Spanish academic prose signals sequence, contrast, cause, concession, and emphasis.", "children": [{"id": "b9ad88c0-02ce-4281-8d51-c2375629d4dc", "type": "subtopic", "title": "Connectors and logical relations", "children": [{"id": "c0bbcd25-3952-4702-8f25-8e482ca1aa34", "type": "concept", "title": "Addition and sequence"}, {"id": "b63bb95c-3a53-4bf5-b29f-2f6b6de8e6d1", "type": "concept", "title": "Cause and result"}, {"id": "63425f7c-6c5b-48e5-853d-a9ebc1201cc3", "type": "concept", "title": "Contrast and concession"}, {"id": "dc846c1e-ba7a-496d-9e01-b8d89a59982c", "type": "concept", "title": "Reformulation and conclusion"}], "description": "Students build a flexible connector repertoire and learn the grammar that follows each connector."}, {"id": "8c9ba84d-446f-4916-8d3b-2b272bcad31e", "type": "subtopic", "title": "Theme-rheme progression", "children": [{"id": "ad1787c6-42ed-4562-a667-b112100ac6f8", "type": "concept", "title": "Topic sentences in Spanish"}, {"id": "4b1ec9b1-b0bd-4031-96cb-80073f1408ad", "type": "concept", "title": "Given-new information flow"}, {"id": "559aac35-ba97-4f57-8177-61f46ab28562", "type": "concept", "title": "Transitions between paragraphs"}, {"id": "6439aa35-73d7-447b-9fde-c830a788dc92", "type": "concept", "title": "Avoiding abrupt shifts"}], "description": "Students learn to manage old and new information so paragraphs feel coherent."}, {"id": "d982e111-093a-41b8-abfe-6b3af4dceba8", "type": "subtopic", "title": "Cohesive devices", "children": [{"id": "ccdc489c-a262-488e-859c-825a7a107278", "type": "concept", "title": "Lexical chains"}, {"id": "315f6f76-1639-40f4-9a06-dee1812e13f3", "type": "concept", "title": "Synonymy and reformulation"}, {"id": "cf9f5995-7dd6-4170-9f42-495e39a06775", "type": "concept", "title": "Pronoun reference"}, {"id": "695c001c-1fa5-4d15-a8e2-7a4de15eb5e0", "type": "concept", "title": "Ellipsis and repetition control"}], "description": "Students practice lexical and grammatical cohesion beyond repeated connector phrases."}]}, {"id": "2bbe65ff-f452-4b95-a8ae-1910eef01d24", "type": "topic", "title": "Register, Style, and Academic Tone", "description": "Students learn to choose language appropriate to audience, genre, and purpose: formal essays, critiques, presentations, correspondence, and culturally situated argument.", "children": [{"id": "908789c9-ed85-4b7a-bc00-f0352e5d3f87", "type": "subtopic", "title": "Register control", "children": [{"id": "d2e4a608-a94a-4cfa-b927-fa2fdf88adce", "type": "concept", "title": "Tuteo and usted"}, {"id": "c19765ae-b345-4660-af06-f6d79805422b", "type": "concept", "title": "Colloquial versus formal vocabulary"}, {"id": "ec53bf12-242b-419b-9c5a-43e890116ebd", "type": "concept", "title": "Formulaic academic expressions"}, {"id": "26db1200-439f-43bd-8f81-b89e34dd8f2c", "type": "concept", "title": "Avoiding anglicized register"}], "description": "Students distinguish informal, neutral, formal, and academic options."}, {"id": "0256555c-75f2-410c-850d-a73ba986167c", "type": "subtopic", "title": "Style and voice", "children": [{"id": "8a56e4e0-9a91-4097-9a39-7a0332ee2e2b", "type": "concept", "title": "Conciseness"}, {"id": "a94cd250-0b17-45e5-9977-fcfdaea15fb4", "type": "concept", "title": "Emphasis"}, {"id": "1a1d137b-0831-4f2f-81fa-36e55d0f215d", "type": "concept", "title": "Nominal versus verbal style"}, {"id": "709af549-cae0-484b-83c4-470510532255", "type": "concept", "title": "Sentence rhythm"}], "description": "Students develop a precise, economical style that still sounds natural in Spanish."}, {"id": "8c72083f-38db-445e-b7e8-6256ae411369", "type": "subtopic", "title": "Genre conventions", "children": [{"id": "55b370a8-1c8a-4329-970b-04eab719b83a", "type": "concept", "title": "Analytical paragraph"}, {"id": "28daa406-1090-401f-9ef0-a41308c6587e", "type": "concept", "title": "Literary or cultural commentary"}, {"id": "b9360499-0eb6-436e-b8b7-38ad7e9e8ac8", "type": "concept", "title": "Academic email and proposal"}, {"id": "da184ce5-218d-4344-ac0d-545051a850a9", "type": "concept", "title": "Oral presentation handout"}], "description": "Students learn the expectations of common advanced undergraduate writing tasks."}]}, {"id": "03cebdd7-377b-4f57-9471-dc2e3e113f73", "type": "topic", "title": "Lexical Precision, Collocation, and Idiomaticity", "description": "World-class composition depends on vocabulary control at the phrase level. This unit trains students to choose words that fit meaning, register, region, and collocation.", "children": [{"id": "d29e686d-da1e-4ba4-9087-c4c27cf68db4", "type": "subtopic", "title": "Lexical selection", "children": [{"id": "45770cf6-f680-4689-8120-985daf0fa041", "type": "concept", "title": "False cognates"}, {"id": "5cc0bf51-df95-4f8d-a9d9-589d62eceae6", "type": "concept", "title": "Polysemy"}, {"id": "7708cb05-9975-475e-9e1b-9e39dec894a8", "type": "concept", "title": "Semantic fields"}, {"id": "425c4983-9bdd-452e-b068-3e0f387e2fa7", "type": "concept", "title": "Academic verbs of analysis"}], "description": "Students move beyond dictionary equivalence into context-sensitive word choice."}, {"id": "bb2073b2-74e6-4e5e-94d5-7f997ec25b71", "type": "subtopic", "title": "Collocations and phraseology", "children": [{"id": "1d81892a-f2b9-471c-aab8-79efc3410a41", "type": "concept", "title": "Verb-noun collocations"}, {"id": "aba6640a-8c2e-4b9e-9f40-0ac85fe2bd76", "type": "concept", "title": "Adjective-noun collocations"}, {"id": "2ae1f3fe-fea9-48fb-8051-d5627533878d", "type": "concept", "title": "Prepositional phrases"}, {"id": "4d2a179d-104f-41eb-a21b-bd6dec0a2745", "type": "concept", "title": "Set academic expressions"}], "d