[{"id": "0e5a23fe-6220-4b1a-a07e-4a82bdd15d6d", "type": "concept", "title": "Evaluative language"}, {"id": "1362479d-c751-423d-982b-d04f34c4f367", "type": "concept", "title": "Evidence integration"}, {"id": "de5fa63d-8724-4c9f-b139-ab99513f129d", "type": "concept", "title": "Counterargument"}, {"id": "568a6652-7892-4d02-ba95-08d87d541ccc", "type": "concept", "title": "Hedging and nuance"}], "description": "Students practice moving from opinion to evidence-based analysis."}, {"id": "9c21fe73-9387-49e3-810a-a831eed49120", "type": "subtopic", "title": "Argument structure", "children": [{"id": "62dff23d-115c-452f-b7d4-3e0899577193", "type": "concept", "title": "Thesis statements"}, {"id": "beb33e36-85a3-405a-b4a4-041dadf45a45", "type": "concept", "title": "Topic sentences"}, {"id": "56a7c88d-771d-46c4-9b3e-92b803d23a96", "type": "concept", "title": "Paragraph unity"}, {"id": "be6075c6-1180-4c3a-969c-d315d21de485", "type": "concept", "title": "Introductions and conclusions"}], "description": "Students build essays around claims, reasons, evidence, and interpretive stakes."}]}, {"id": "20fc5457-769f-424e-b5ba-74c1b85c6013", "type": "topic", "title": "Research-Supported Essay and Revision Portfolio", "description": "The final unit integrates the course: students plan, draft, research, revise, edit, and present polished Spanish prose using a mature grammar toolkit.", "children": [{"id": "bba63a89-8cc2-4c7d-901d-119a0f3210fc", "type": "subtopic", "title": "Research process", "children": [{"id": "ef5d2763-4801-4201-99d9-42ff1edacfbb", "type": "concept", "title": "Research questions"}, {"id": "7a7496cb-9a3e-4961-8866-2f9ff7c68907", "type": "concept", "title": "Source evaluation"}, {"id": "a37f4504-1f86-45f5-aa37-0413171c8fc9", "type": "concept", "title": "Annotated bibliography"}, {"id": "1bf869c8-4e4b-4701-8fdf-081e8da391e3", "type": "concept", "title": "Citation ethics"}], "description": "Students learn to find, evaluate, and integrate scholarly and credible Spanish-language sources."}, {"id": "970e20e5-90a1-49ce-82f0-148c2240ac65", "type": "subtopic", "title": "Drafting and revision", "children": [{"id": "5e7b3acb-ed90-4bd0-9005-f144579d96a9", "type": "concept", "title": "Outlining"}, {"id": "21708e65-588b-4fe0-b442-f121025b6391", "type": "concept", "title": "Reverse outlining"}, {"id": "873cce85-6ee2-4105-9e59-9a52e9a08d2e", "type": "concept", "title": "Peer review"}, {"id": "4e0b97f5-7a40-4f1e-b9fe-f8dbac951351", "type": "concept", "title": "Global versus sentence-level revision"}], "description": "Students treat writing as staged work rather than a one-pass performance."}, {"id": "0382b10c-43a7-4c69-9f1f-0dcc072a18a2", "type": "subtopic", "title": "Editing portfolio", "children": [{"id": "9474b26b-4f91-4cb1-970c-9493b1df75f3", "type": "concept", "title": "Error log"}, {"id": "a5442b62-22a2-435a-9c7c-addfbf6ddef7", "type": "concept", "title": "Style sheet"}, {"id": "48228fb6-7ed7-4583-a116-84c57dffe6cc", "type": "concept", "title": "Grammar self-diagnosis"}, {"id": "b0c6985d-2df7-487c-a84b-f8d61e26ad51", "type": "concept", "title": "Final reflective memo"}], "description": "Students demonstrate progress through tracked revisions, reflective commentary, and final polish."}]}], "dbBacked": true}$agrcjson$::jsonb,
