anguage sources."}, {"id": "970e20e5-90a1-49ce-82f0-148c2240ac65", "type": "subtopic", "title": "Drafting and revision", "children": [{"id": "5e7b3acb-ed90-4bd0-9005-f144579d96a9", "type": "concept", "title": "Outlining"}, {"id": "21708e65-588b-4fe0-b442-f121025b6391", "type": "concept", "title": "Reverse outlining"}, {"id": "873cce85-6ee2-4105-9e59-9a52e9a08d2e", "type": "concept", "title": "Peer review"}, {"id": "4e0b97f5-7a40-4f1e-b9fe-f8dbac951351", "type": "concept", "title": "Global versus sentence-level revision"}], "description": "Students treat writing as staged work rather than a one-pass performance."}, {"id": "0382b10c-43a7-4c69-9f1f-0dcc072a18a2", "type": "subtopic", "title": "Editing portfolio", "children": [{"id": "9474b26b-4f91-4cb1-970c-9493b1df75f3", "type": "concept", "title": "Error log"}, {"id": "a5442b62-22a2-435a-9c7c-addfbf6ddef7", "type": "concept", "title": "Style sheet"}, {"id": "48228fb6-7ed7-4583-a116-84c57dffe6cc", "type": "concept", "title": "Grammar self-diagnosis"}, {"id": "b0c6985d-2df7-487c-a84b-f8d61e26ad51", "type": "concept", "title": "Final reflective memo"}], "description": "Students demonstrate progress through tracked revisions, reflective commentary, and final polish."}]}], "dbBacked": true}$agrcjson$::jsonb,
